// Contoh lain
function formatNilai(nilai: string | number | boolean) {
  if (typeof nilai === 'string') return nilai.trim();
  if (typeof nilai === 'number') return nilai.toLocaleString('id-ID');
  return nilai ? 'Ya' : 'Tidak'; // sudah pasti boolean
}

function formatTanggal(nilai: Date | string) {
  if (nilai instanceof Date) {
    // nilai adalah Date
    return nilai.toLocaleDateString('id-ID');
  }
  // Di sini, nilai pasti string
  return new Date(nilai).toLocaleDateString('id-ID');
}

// Narrowing error
function tanganiError(error: unknown) {
  if (error instanceof Error) {
    // error adalah Error object — bisa akses .message
    console.error(error.message);
  } else if (typeof error === 'string') {
    console.error(error);
  } else {
    console.error('Error tidak dikenal');
  }
}

