// Property 'tipe' adalah discriminant-nya
type BerhasilLogin = {
  tipe: 'berhasil';    // discriminant
  user: User;
  token: string;
};

type GagalLogin = {
  tipe: 'gagal';       // discriminant
  pesan: string;
  kodeError: number;
};

type HasilLogin = BerhasilLogin | GagalLogin;

function tanganiLogin(hasil: HasilLogin) {
  // TypeScript narrow otomatis berdasarkan 'tipe'
  if (hasil.tipe === 'berhasil') {
    // TS tahu ini BerhasilLogin
    console.log(`Selamat datang, ${hasil.user.nama}!`);
    simpanToken(hasil.token);
  } else {
    // TS tahu ini GagalLogin
    console.log(`Login gagal: ${hasil.pesan}`);
    tampilkanError(hasil.kodeError);
  }
}

type Aksi =
  | { tipe: 'TAMBAH_ITEM'; payload: Produk }
  | { tipe: 'HAPUS_ITEM'; payload: { id: number } }
  | { tipe: 'UPDATE_JUMLAH'; payload: { id: number; jumlah: number } }
  | { tipe: 'KOSONGKAN' };

function reducer(state: KeranjangState, aksi: Aksi): KeranjangState {
  switch (aksi.tipe) {
    case 'TAMBAH_ITEM':
      // aksi.payload bertipe Produk
      return { ...state, items: [...state.items, aksi.payload] };

    case 'HAPUS_ITEM':
      // aksi.payload bertipe { id: number }
      return {
        ...state,
        items: state.items.filter(i => i.id !== aksi.payload.id)
      };

    case 'UPDATE_JUMLAH':
      // aksi.payload bertipe { id: number; jumlah: number }
      return {
        ...state,
        items: state.items.map(i =>
          i.id === aksi.payload.id
            ? { ...i, jumlah: aksi.payload.jumlah }
            : i
        )
      };

    case 'KOSONGKAN':
      // aksi tidak punya payload
      return { ...state, items: [] };
  }
}

type Notifikasi =
  | { tipe: 'info'; pesan: string }
  | { tipe: 'sukses'; pesan: string }
  | { tipe: 'peringatan'; pesan: string; aksi?: string }
  | { tipe: 'error'; pesan: string; kode: number };

function tampilkanNotifikasi(notif: Notifikasi) {
  switch (notif.tipe) {
    case 'info': return tampilkanInfo(notif.pesan);
    case 'sukses': return tampilkanSukses(notif.pesan);
    case 'peringatan': return tampilkanPeringatan(notif.pesan, notif.aksi);
    case 'error': return tampilkanError(notif.pesan, notif.kode);
    default:
      // Kalau semua case sudah ditangani, TypeScript tahu
      // notif di sini bertipe 'never'
      // Kalau ada tipe baru di union yang belum ditambahkan ke switch,
      // baris ini akan ERROR — kamu terhindar dari bug yang tersembunyi!
      const _cekSelesai: never = notif;
      throw new Error(`Tipe notifikasi tidak dikenal: ${_cekSelesai}`);
  }
}
